// LabCheck: runs all eight parts of the lab and prints what each part
// produces. Do not edit this file. Your output must match the expected
// output in the lab handout, character for character.
public static class LabCheck
{
    public static void Run()
    {
        Console.WriteLine("=== CSCI 1260 DATA STRUCTURES LAB ===");
        Console.WriteLine();
        RunPart("Part A: array tools", PartA);
        Console.WriteLine();
        RunPart("Part B: MyList", PartB);
        Console.WriteLine();
        RunPart("Part C: MyStack", PartC);
        Console.WriteLine();
        RunPart("Part D: MyQueue", PartD);
        Console.WriteLine();
        RunPart("Part E: dictionaries", PartE);
        Console.WriteLine();
        RunPart("Part F: MyHashTable", PartF);
        Console.WriteLine();
        RunPart("Part G: filter and transform", PartG);
        Console.WriteLine();
        RunPart("Part H: sort, summarize, group", PartH);
    }

    // A part you have not finished prints one line instead of stopping
    // the whole program, so the other parts still run.
    private static void RunPart(string title, Action part)
    {
        Console.WriteLine(title);
        try
        {
            part();
        }
        catch (NotImplementedException)
        {
            Console.WriteLine("  Not finished yet.");
        }
    }

    private static void Line(string label, object? value)
    {
        Console.WriteLine("  {0,-22}{1}", label, value);
    }

    private static void PrintList(string label, IEnumerable<string> items)
    {
        Console.WriteLine("  " + label);
        foreach (string item in items)
        {
            Console.WriteLine("    " + item);
        }
    }

    // ---------- Parts A to D: structures by position ----------

    private static void PartA()
    {
        int[] data = { 10, 20, 30, 40, 50, 0, 0, 0 };
        int count = 5;
        Line("Start:", ArrayTools.Show(data, count));

        count = ArrayTools.InsertAt(data, count, 1, 15);
        Line("InsertAt(1, 15):", ArrayTools.Show(data, count));
        Line("IndexOf(40):", ArrayTools.IndexOf(data, count, 40));
        Line("IndexOf(99):", ArrayTools.IndexOf(data, count, 99));

        count = ArrayTools.RemoveAt(data, count, 0);
        Line("RemoveAt(0):", ArrayTools.Show(data, count));
        count = ArrayTools.RemoveAt(data, count, 4);
        Line("RemoveAt(4):", ArrayTools.Show(data, count));
        Line("Slots in use:", count + " of " + data.Length);
    }

    private static void PartB()
    {
        MyList<int> numbers = new MyList<int>();
        for (int i = 1; i <= 9; i++)
        {
            numbers.Add(i);
        }
        Line("After 9 adds:", "Count " + numbers.Count + ", Capacity " + numbers.Capacity);

        MyList<string> letters = new MyList<string>();
        letters.Add("B");
        letters.Add("D");
        letters.Insert(0, "A");
        letters.Insert(2, "C");
        letters.Insert(4, "E");
        Line("After inserts:", letters);
        Line("Count, Capacity:", letters.Count + ", " + letters.Capacity);

        letters.RemoveAt(0);
        Line("RemoveAt(0):", letters);
        letters[1] = "Z";
        Line("Set [1] to Z:", letters);
        Line("IndexOf(\"D\"):", letters.IndexOf("D"));
        Line("IndexOf(\"Q\"):", letters.IndexOf("Q"));

        try
        {
            string unused = letters[4];
            Line("letters[4]:", "allowed (should be refused)");
        }
        catch (ArgumentOutOfRangeException)
        {
            Line("letters[4]:", "refused");
        }
    }

    private static void PartC()
    {
        MyStack<string> stack = new MyStack<string>();
        stack.Push("A");
        stack.Push("B");
        stack.Push("C");
        Line("Peek:", stack.Peek());

        string popped = stack.Pop();
        popped += " " + stack.Pop();
        popped += " " + stack.Pop();
        Line("Pop three times:", popped);
        Line("IsEmpty:", stack.IsEmpty);

        try
        {
            stack.Pop();
            Line("Pop when empty:", "allowed (should be refused)");
        }
        catch (InvalidOperationException)
        {
            Line("Pop when empty:", "refused");
        }

        string[] tests =
        {
            "Console.WriteLine(list[0]);",
            "{ [ ( ) ] }",
            "( [ ) ]",
            "( ( )",
            "( ) )",
        };
        Console.WriteLine("  Brackets:");
        foreach (string test in tests)
        {
            Console.WriteLine("    {0,-30}{1}", test, BracketChecker.IsBalanced(test));
        }
    }

    private static void PartD()
    {
        MyQueue<string> queue = new MyQueue<string>();
        queue.Enqueue("A");
        queue.Enqueue("B");
        queue.Enqueue("C");
        string served = queue.Dequeue();
        served += " " + queue.Dequeue();
        Line("Dequeue twice:", served);

        queue.Enqueue("D");
        queue.Enqueue("E");    // E and F wrap around to the start
        queue.Enqueue("F");
        Line("Peek:", queue.Peek());
        queue.Enqueue("G");    // all four slots are full, so the queue grows
        Line("Count:", queue.Count);

        string rest = "";
        while (!queue.IsEmpty)
        {
            rest += queue.Dequeue() + " ";
        }
        Line("Dequeue all:", rest.Trim());

        try
        {
            queue.Dequeue();
            Line("Dequeue when empty:", "allowed (should be refused)");
        }
        catch (InvalidOperationException)
        {
            Line("Dequeue when empty:", "refused");
        }

        MyQueue<Visit> line = new MyQueue<Visit>();
        line.Enqueue(new Visit("Ada", 12));
        line.Enqueue(new Visit("Ben", 5));
        line.Enqueue(new Visit("Cy", 8));
        MyList<string> finished = OfficeHours.Run(line, 5);
        Console.WriteLine("  Office hours, 5 minute turns:");
        for (int i = 0; i < finished.Count; i++)
        {
            Console.WriteLine("    " + finished[i]);
        }
    }

    // ---------- Parts E to H: finding and asking ----------

    private static void PartE()
    {
        CourseCatalog catalog = new CourseCatalog();
        foreach (Course c in SampleData.Courses())
        {
            catalog.AddCourse(c.Code, c.Title);
        }
        Line("Courses added:", catalog.Count);
        Line("Add CSCI 1260 again:", catalog.AddCourse("CSCI 1260", "Duplicate"));
        Line("TitleFor(CSCI 1260):", catalog.TitleFor("CSCI 1260"));
        Line("TitleFor(ARTS 1010):", catalog.TitleFor("ARTS 1010"));

        Dictionary<string, int> counts = WordCount.Count("To be, or not to be: that is the question.");
        Console.WriteLine("  Words, most common first:");
        foreach (KeyValuePair<string, int> pair in counts.OrderByDescending(p => p.Value).ThenBy(p => p.Key))
        {
            Console.WriteLine("    {0,-12}{1}", pair.Key, pair.Value);
        }
        Line("Distinct words:", counts.Count);
    }

    private static void PartF()
    {
        MyHashTable<int, string> table = new MyHashTable<int, string>(7);
        table.Add(4417, "Ada");
        table.Add(2290, "Ben");
        table.Add(3305, "Cy");
        table.Add(5126, "Dee");
        table.Add(6024, "Eli");
        Line("Count:", table.Count);
        Line("Bucket sizes:", table.BucketSizes());

        Line("Find 3305:", table.TryGetValue(3305, out string? found) ? found : "not found");
        Line("Find 9999:", table.TryGetValue(9999, out string? missing) ? missing : "not found");

        try
        {
            table.Add(2290, "Bea");
            Line("Add 2290 again:", "allowed (should be refused)");
        }
        catch (ArgumentException)
        {
            Line("Add 2290 again:", "refused");
        }
    }

    private static void PartG()
    {
        List<Course> courses = SampleData.Courses();
        Line("Open course codes:", string.Join(", ", CourseQueries.OpenCourseCodes(courses)));
        PrintList("Four credit titles:", CourseQueries.FourCreditTitles(courses));
        PrintList("Seats left:", CourseQueries.SeatsLeftReport(courses));
    }

    private static void PartH()
    {
        List<Course> courses = SampleData.Courses();
        Line("Top three:", string.Join(", ", CourseQueries.TopThreeByEnrollment(courses)));
        Line("Total enrolled:", CourseQueries.TotalEnrolled(courses));
        Line("Full courses:", CourseQueries.FullCourseCount(courses));
        Line("ByCode[MATH 1910]:", CourseQueries.ByCode(courses)["MATH 1910"].Title);
        PrintList("Departments:", CourseQueries.DepartmentReport(courses));
    }
}
